<?php defined('BASEPATH') OR exit('No direct script access allowed');class Webhook_model extends CI_Model{function __construct(){parent::__construct();$this->load->database();}function receive($org,$source,$payload,$verified,$type=NULL){if(!$this->db->where('id',$org)->count_all_results('organizations'))return NULL;$r=array('id'=>$this->uuid(),'organization_id'=>$org,'source'=>substr($source,0,100),'event_type'=>$type,'payload'=>json_encode($payload),'verified'=>$verified?1:0,'status'=>'RECEIVED','replay_count'=>0,'created_at'=>date('Y-m-d H:i:s'));$this->db->insert('inbound_webhooks',$r);return $this->view($r);}function listing($org,$source,$status,$p,$pp){$this->db->from('inbound_webhooks')->where('organization_id',$org);if($source)$this->db->where('source',$source);if($status)$this->db->where('status',strtoupper($status));$n=$this->db->count_all_results();$this->db->where('organization_id',$org);if($source)$this->db->where('source',$source);if($status)$this->db->where('status',strtoupper($status));$r=$this->db->order_by('created_at','DESC')->limit($pp,($p-1)*$pp)->get('inbound_webhooks')->result_array();return array('items'=>array_map(array($this,'view'),$r),'pagination'=>array('page'=>$p,'perPage'=>$pp,'total'=>$n,'totalPages'=>(int)ceil($n/$pp)));}function one($id,$org){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('inbound_webhooks')->row_array();return $r?$this->view($r):NULL;}function replay($id,$org){$r=$this->db->where(array('id'=>$id,'organization_id'=>$org))->get('inbound_webhooks')->row_array();if(!$r)return NULL;$now=date('Y-m-d H:i:s');$this->db->where('id',$id)->set('replay_count','replay_count+1',FALSE)->update('inbound_webhooks',array('status'=>'REPLAYED','last_replayed_at'=>$now));$r['replay_count']++;$r['status']='REPLAYED';$r['last_replayed_at']=$now;return $this->view($r);}function remove($id,$org){$this->db->where(array('id'=>$id,'organization_id'=>$org))->delete('inbound_webhooks');return $this->db->affected_rows()>0;}function view($r){return array('id'=>$r['id'],'organizationId'=>$r['organization_id'],'source'=>$r['source'],'eventType'=>$r['event_type'],'payload'=>json_decode($r['payload'],TRUE)?:array(),'verified'=>(bool)$r['verified'],'status'=>strtolower($r['status']),'replayCount'=>(int)$r['replay_count'],'lastReplayedAt'=>$r['last_replayed_at']??NULL,'createdAt'=>$r['created_at']);}private function uuid(){$b=random_bytes(16);$b[6]=chr((ord($b[6])&15)|64);$b[8]=chr((ord($b[8])&63)|128);return vsprintf('%s%s-%s-%s-%s-%s%s%s',str_split(bin2hex($b),4));}}
